def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count paths of K moves through empty cells without visiting a cell twice.

    Paths may start at any empty cell and use the four orthogonal directions.
    The starting cell is included in the K+1 distinct cells of each path.

    Args:
        H: Number of rows (1 <= H <= 10).
        W: Number of columns (1 <= W <= 10).
        K: Number of moves (1 <= K <= 11).
        grid: H strings of length W, with '.' empty and '#' blocked.

    Returns:
        The number of valid paths of length K+1.

    >>> count_paths(2, 2, 2, ['.#', '..'])
    2
    >>> count_paths(2, 3, 1, ['.#.', '#.#'])
    0
    """
    cells = {
        (r, c): i
        for i, (r, c) in enumerate(
            (r, c)
            for r in range(H)
            for c in range(W)
            if grid[r][c] == '.'
        )
    }
    if len(cells) <= K:
        return 0

    neighbors = [[] for _ in cells]
    for (r, c), i in cells.items():
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            j = cells.get((r + dr, c + dc))
            if j is not None:
                neighbors[i].append(j)

    visited = [False] * len(cells)

    def dfs(cell: int, remaining: int) -> int:
        if remaining == 0:
            return 1
        visited[cell] = True
        total = 0
        for nxt in neighbors[cell]:
            if not visited[nxt]:
                total += dfs(nxt, remaining - 1)
        visited[cell] = False
        return total

    return sum(dfs(start, K) for start in range(len(cells)))

from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers in [low, high] with equal even/odd digit counts and divisible by k.

    Args:
        low: Inclusive lower bound, 0 < low <= high <= 10**9.
        high: Inclusive upper bound.
        k: Divisor, 0 < k <= 20.

    >>> count_beautiful_integers(10, 20, 3)
    2
    >>> count_beautiful_integers(1, 10, 1)
    1
    >>> count_beautiful_integers(5, 5, 2)
    0
    """
    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = tuple(map(int, str(bound)))
        size = len(digits)

        @lru_cache(None)
        def dp(pos: int, balance: int, remainder: int,
               started: bool, tight: bool) -> int:
            if abs(balance) > size - pos:
                return 0
            if pos == size:
                return int(started and balance == 0 and remainder == 0)
            limit = digits[pos] if tight else 9
            total = 0
            for digit in range(limit + 1):
                next_tight = tight and digit == digits[pos]
                if not started and digit == 0:
                    total += dp(pos + 1, 0, 0, False, next_tight)
                else:
                    total += dp(pos + 1,
                                balance + (1 if digit % 2 == 0 else -1),
                                (remainder * 10 + digit) % k,
                                True, next_tight)
            return total

        return dp(0, 0, 0, False, True)

    return count_up_to(high) - count_up_to(low - 1)

def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum the products of all good sequences modulo 998244353.

    For every adjacent pair, the product of the numerator and denominator
    of its reduced ratio must be a[i]. All sequence elements are positive
    integers and their collective gcd is one.
    """
    mod = 998244353
    # A prime power in a reduced ratio lies wholly on one side. Therefore,
    # the exponents of each prime form a walk with prescribed step sizes.
    # Different primes can be counted independently.
    factors = {}
    for index, value in enumerate(a):
        divisor = 2
        while divisor * divisor <= value:
            if value % divisor == 0:
                exponent = 0
                while value % divisor == 0:
                    value //= divisor
                    exponent += 1
                if divisor not in factors:
                    factors[divisor] = [0] * (n - 1)
                factors[divisor][index] = exponent
            divisor += 1
        if value > 1:
            if value not in factors:
                factors[value] = [0] * (n - 1)
            factors[value][index] = 1

    answer = 1
    for prime, steps in factors.items():
        limit = max(sum(steps), n * max(steps))
        powers = [1] * (limit + 1)
        for exponent in range(1, limit + 1):
            powers[exponent] = powers[exponent - 1] * prime % mod

        # Normalize every partial walk so its minimum is zero. dp[h] is
        # the sum of its product weights when its last exponent is h.
        dp = [1]
        for length, step in enumerate(steps, 1):
            if step == 0:
                dp = [weight * powers[height] % mod
                      for height, weight in enumerate(dp)]
                continue

            next_dp = [0] * (len(dp) + step)
            for height, weight in enumerate(dp):
                if not weight:
                    continue
                upward = height + step
                next_dp[upward] = (
                    next_dp[upward] + weight * powers[upward]
                ) % mod
                if height >= step:
                    downward = height - step
                    next_dp[downward] = (
                        next_dp[downward] + weight * powers[downward]
                    ) % mod
                else:
                    # The new endpoint is the new minimum. Raising the
                    # previous 'length' exponents restores minimum zero.
                    next_dp[0] = (
                        next_dp[0] + weight * powers[length * (step - height)]
                    ) % mod
            dp = next_dp
        answer = answer * (sum(dp) % mod) % mod
    return answer

from functools import lru_cache


@lru_cache(maxsize=None)
def _nonzero_completions(remaining: int, digit_sum: int, digit_product: int) -> int:
    """Count beautiful completions using only nonzero digits."""
    if remaining == 0:
        return int(digit_sum > 0 and digit_product % digit_sum == 0)
    return sum(
        _nonzero_completions(remaining - 1, digit_sum + digit, digit_product * digit)
        for digit in range(1, 10)
    )


def _count_up_to(bound: int) -> int:
    if bound <= 0:
        return 0

    digits = [int(char) for char in str(bound)]
    length = len(digits)
    nonzero_count = sum(9 ** size for size in range(1, length))
    beautiful_nonzero = sum(
        _nonzero_completions(size, 0, 1) for size in range(1, length)
    )

    digit_sum = 0
    digit_product = 1
    for index, limit in enumerate(digits):
        remaining = length - index - 1
        for digit in range(1, limit):
            nonzero_count += 9 ** remaining
            beautiful_nonzero += _nonzero_completions(
                remaining, digit_sum + digit, digit_product * digit
            )
        if limit == 0:
            break
        digit_sum += limit
        digit_product *= limit
    else:
        nonzero_count += 1
        beautiful_nonzero += int(digit_product % digit_sum == 0)

    # Every positive integer containing a zero has digit product zero.
    return bound - nonzero_count + beautiful_nonzero


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

